package com.xyz.question_bank_management_system.modules.recommendation.controller;
import com.xyz.question_bank_management_system.common.ApiResponse; import com.xyz.question_bank_management_system.modules.recommendation.dto.*; import com.xyz.question_bank_management_system.modules.recommendation.entity.StudentResourceRecommendation; import com.xyz.question_bank_management_system.modules.recommendation.service.ResourceRecommendationService; import com.xyz.question_bank_management_system.util.SecurityContextUtil; import lombok.RequiredArgsConstructor; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/learning/recommendation-records") @RequiredArgsConstructor @PreAuthorize("hasRole('STUDENT')") public class ResourceRecommendationController {private final ResourceRecommendationService service; @PostMapping("/refresh") public ApiResponse<List<StudentResourceRecommendation>> refresh(){return ApiResponse.ok(service.refresh(SecurityContextUtil.getUserId()));} @GetMapping public ApiResponse<List<StudentResourceRecommendation>> mine(){return ApiResponse.ok(service.mine(SecurityContextUtil.getUserId()));} @PutMapping("/{id}/status") public ApiResponse<Void> status(@PathVariable Long id,@RequestBody RecommendationStatusRequest r){service.updateStatus(id,r,SecurityContextUtil.getUserId());return ApiResponse.ok();} @PostMapping("/resources/{resourceId}/feedback") public ApiResponse<Long> feedback(@PathVariable Long resourceId,@RequestBody ResourceFeedbackRequest r){return ApiResponse.ok(service.feedback(resourceId,r,SecurityContextUtil.getUserId()));}}
